tDemonTower_Text["BossNameExra"] = {"FlameGiant(Elite)","FrostGiant(Elite)"}

tDemonTower_Text["BossSay"] = {}
--成功挑战前
tDemonTower_Text["BossSay"][1] = {}
tDemonTower_Text["BossSay"][1][1] = {"Guguga! Guguguga! (You don`t understand the Great Pheasant`s words,","but its arrogant expression is really annoying.)"}
tDemonTower_Text["BossSay"][1][2] = {"Is my birthday approaching? There are so many human sacrifices coming to me recently.","No hurry, I`ll peel your skin off gently before eating you raw."}
tDemonTower_Text["BossSay"][1][3] = {"(A voice inclines your ear when you`re moving close to the Water Terror.)","Let me out... Let me out... I need water... Just water... Water!!!"}
tDemonTower_Text["BossSay"][1][4] = {"Most humans are guilty of greed, wrath or lust.","For the compassionate Buddha, I`d like to drain your blood and give you a chance of rebirth. Be grateful!"}
tDemonTower_Text["BossSay"][1][5] = {"You must feel ashamed for sealing me by using ignoble tricks. Fight me if you dare!","So, they brought you here? Good, I can`t wait to fight, tearing you into pieces."}
tDemonTower_Text["BossSay"][1][6] = {"(The devil, in front of you, is getting impatient with corrosive saliva constantly dripping from its mouth.)","I`m so hungry... I want something to eat! YUM...YUM..."}
tDemonTower_Text["BossSay"][1][7] = {"Howling... Howling (This alien devil was struck in the formation,","but you can still feel its wild wrath and power through its howling. "}
tDemonTower_Text["BossSay"][1][8] = {"Come here... I know you love me... Hahaha... I got an idea. If you set me free from the seal,","I`ll give you everything you want. I promise."}
tDemonTower_Text["BossSay"][1][9] = {"I felt like I`m going to die of boredom. Thanks for coming!","If you want to get frozen, talk to my brother, Frost Giant, while if you want to get burnt, come to me."}

--成功挑战后
tDemonTower_Text["BossSay"][2] = {}
tDemonTower_Text["BossSay"][2][1] = {"Gu... Gugu... Guguga... (The Great Pheasant with feathers disheveled looks really depressed.","It seems you`ve beaten it hard."}
tDemonTower_Text["BossSay"][2][2] = {"Stop... Stop it! Let`s stop fighting. I won`t eat you, okay?","Hey, alright, I`ll transfer to be a vegetarian. No more demands."}
tDemonTower_Text["BossSay"][2][3] = {"(The Water Terror was sealed again after you defeated it,","and the ghostly voice disappeared."}
tDemonTower_Text["BossSay"][2][4] = {"Your sin is too great for me to purify.","Please go ahead."}
tDemonTower_Text["BossSay"][2][5] = {"Aha, I haven`t had a good fight like this in a long time. (Soul Strangler looked at you with curiosity.)","You`re quite strong. Not many of you are able to defeat me."}
tDemonTower_Text["BossSay"][2][6] = {"(The Infernal Glutton fell down after your last strike.) I hate...","HUNGER! I want to eat... Anyone hear me?"}
tDemonTower_Text["BossSay"][2][7] = {"(You finally defeated the Alien Dragon, and sealed it","in the magic formation again, leaving its howling lingering round the Tower of Mystery)"}
tDemonTower_Text["BossSay"][2][8] = {"Humph... You`ll regret your decision of rejecting me!","One day, I`ll let you drown in misery worse than death."}
tDemonTower_Text["BossSay"][2][9] = {"It brought no honor to your victory this time. You could never defeat me if my power was not sealed.","When I get out, I`ll trample you deep into the ground."}

